def inverse_current_ack_source(name, raw):
    if name not in ACK_SOURCE_INVERSES:
        return raw
    binding = ACK_SOURCE_INVERSES[name]
    text = raw.decode('utf-8')
    if '\r' in text:
        remainder = text.replace('\r\n', '')
        if '\r' in remainder or '\n' in remainder:
            raise AssertionError('Mixed acknowledgment fixture source newlines refused')
        text = text.replace('\r\n', '\n')
    data = text.encode('utf-8')
